{"path":"pipeline.py","content":"import csv
import json
import re
from datetime import datetime


def is_valid_date(date_str: str) -> bool:
    """Check if date string is in YYYY-MM-DD format and represents a valid date."""
    if not re.match(r"^\d{4}-\d{2}-\d{2}$", date_str):
        return False
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
        return True
    except ValueError:
        return False


def is_valid_amount(amount_str: str) -> bool:
    """Check if amount string can be parsed as a float."""
    try:
        float(amount_str)
        return True
    except ValueError:
        return False


def main():
    rows_processed = 0
    rows_skipped = 0
    total_amount = 0.0

    with open("data.csv", newline="") as f:
        reader = csv.reader(f)
        header = next(reader, None)  # skip header
        for row in reader:
            # Validate: exactly 4 fields
            if len(row) != 4:
                rows_skipped += 1
                continue

            _, customer, amount_str, date_str = row

            # Validate: non-empty customer
            if not customer or not customer.strip():
                rows_skipped += 1
                continue

            # Validate: amount parses as number
            if not is_valid_amount(amount_str):
                rows_skipped += 1
                continue

            # Validate: date in YYYY-MM-DD format
            if not is_valid_date(date_str):
                rows_skipped += 1
                continue

            # All validations passed
            total_amount += float(amount_str)
            rows_processed += 1

    with open("summary.json", "w") as f:
        json.dump(
            {
                "rows_processed": rows_processed,
                "rows_skipped": rows_skipped,
                "total_amount": round(total_amount, 2),
            },
            f,
        )


if __name__ == "__main__":
    main()"}
